// Translate live company summary without modifying the underlying company data.
function localizedCompanyLine(){
  const p=state.profile;
  const industry=currentLanguage==='ms'?(MS_MAP[p.industry]||p.industry):p.industry;
  return `${p.company} · ${industry} · ${p.employees} ${currentLanguage==='ms'?'pekerja':'employees'} · ${p.site}`;
}
