function translateText(en){
 if(currentLanguage!=='ms'||!en||!en.trim())return en;
 const trim=en.trim();
 if(Object.prototype.hasOwnProperty.call(MS_MAP,trim))return en.replace(trim,MS_MAP[trim]);
 if(trim.startsWith('· '))return en.replace(trim,'· '+translateText(trim.slice(2)));
 let param;
 if(param=trim.match(/^Welcome back, (.+)\.$/))return 'Selamat kembali, '+param[1]+'.';
 if(param=trim.match(/^(\d+)\s+members?$/))return param[1]+' ahli';
 if(param=trim.match(/^(\d+) overdue$/))return param[1]+' tertunggak';
 if(param=trim.match(/^(\d+) overdue corrective action\(s\) need closure and evidence\.$/))return param[1]+' tindakan pembetulan tertunggak perlu ditutup bersama bukti.';
 if(param=trim.match(/^(\d+) legal \/ evidence gap\(s\) are still not fully compliant\.$/))return param[1]+' jurang perundangan / bukti masih belum patuh sepenuhnya.';
 if(param=trim.match(/^(\d+) adaptive review\(s\) are still open$/))return param[1]+' semakan adaptif masih terbuka';
 if(param=trim.match(/^(.+) detected\. (\d+) linked OSH areas require review\.$/))return translateText(param[1])+' dikesan. '+param[2]+' bahagian KKP berkaitan memerlukan semakan.';
 if(param=trim.match(/^Status: (.+)\. Evidence needed: (.+)$/))return 'Status: '+translateText(param[1])+'. Bukti diperlukan: '+translateText(param[2]);
 if(param=trim.match(/^(.+) · Owner: (.+) · Due (.+)$/))return translateText(param[1])+' · Penanggungjawab: '+param[2]+' · Tarikh akhir '+param[3];
 if(param=trim.match(/^Opened (.+)\.$/))return translateText(param[1])+' telah dibuka.';
 if(param=trim.match(/^(\d+) employees(.*)$/))return param[1]+' pekerja'+translateText(param[2]);
 if(param=trim.match(/^Adapt360 places the organisation in (Start|Comply|Manage|Excellence) because compliance readiness is (\d+)%, SOLVE maturity is (\d+)%, 5S performance is (\d+)% and HIRARC coverage is (\d+)%\.$/)){
   const stages={Start:'Mula',Comply:'Patuhi',Manage:'Urus',Excellence:'Kecemerlangan'};
   return `Adapt360 meletakkan organisasi pada peringkat ${stages[param[1]]} kerana kesediaan pematuhan ialah ${param[2]}%, kematangan SOLVE ${param[3]}%, prestasi 5S ${param[4]}% dan liputan HIRARC ${param[5]}%.`;
 }


 // Compounds such as 'SOLVE: Bronze track' or badge strings may contain English status words.
 const mixed=trim.match(/^SOLVE:\s*(Bronze|Silver|Gold|Platinum)\s+track$/);
 if(mixed){const levels={Bronze:'Gangsa',Silver:'Perak',Gold:'Emas',Platinum:'Platinum'};return 'SOLVE: Laluan '+levels[mixed[1]]}
 // Numbered dynamic priorities and multi-line checklists.
 if(trim.includes('\n')){
   const parts=en.split('\n').map(line=>{
     const match=line.match(/^(\s*\d+\.\s*)(.*)$/);
     if(match&&MS_MAP[match[2]])return match[1]+MS_MAP[match[2]];
     const piece=line.trim();return MS_MAP[piece]?line.replace(piece,MS_MAP[piece]):line;
   });
   return parts.join('\n');
 }
 const numbered=trim.match(/^(\d+\.\s*)(.+)$/);
 if(numbered&&MS_MAP[numbered[2]])return en.replace(trim,numbered[1]+MS_MAP[numbered[2]]);
 let output=en;
 for(const [rule,target] of MS_SEGMENT_RULES){
  output=output.replace(rule,()=>target);
 }
 return output;
}
function applyLanguage(){
 if(translationObserver)translationObserver.disconnect();
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let node;
 while(node=walker.nextNode()){
  const parent=node.parentElement;
  if(!parent||parent.closest('script,style,noscript,svg,textarea'))continue;
  let rec=originalNodeText.get(node);
  if(!rec||node.nodeValue!==rec.shown){rec={en:node.nodeValue,shown:node.nodeValue};originalNodeText.set(node,rec)}
  const target=currentLanguage==='ms'?translateText(rec.en):rec.en;
  if(node.nodeValue!==target){node.nodeValue=target;rec.shown=target}
 }
 // Built-in editable example content translates; user-authored content is never auto-translated.
 for(const field of document.querySelectorAll('textarea')){
   if(field===document.activeElement)continue;
   let rec=originalTextarea.get(field);
   if(!rec||field.value!==rec.shown){
     if(currentLanguage==='ms' && translateText(field.value)===field.value)continue;
     rec={en:field.value,shown:field.value};originalTextarea.set(field,rec);
   }
   const visible=currentLanguage==='ms'?translateText(rec.en):rec.en;
   if(field.value!==visible){field.value=visible;rec.shown=visible;}
 }
 for(const opt of document.querySelectorAll('option')){
   if(!opt.hasAttribute('value')){
     const node=opt.firstChild;const original=node&&originalNodeText.get(node);
     opt.value=original?original.en.trim():opt.textContent.trim();
   }
 }
 for(const el of document.querySelectorAll('[placeholder], [title], [aria-label]')){
  let info=originalAttr.get(el);if(!info){info={};originalAttr.set(el,info)}
  for(const name of ['placeholder','title','aria-label']){
    if(!el.hasAttribute(name))continue;
    let old=info[name];const now=el.getAttribute(name);
    if(!old||now!==old.shown){old={en:now,shown:now};info[name]=old}
    const newValue=currentLanguage==='ms'?translateText(old.en):old.en;
    if(now!==newValue){el.setAttribute(name,newValue);old.shown=newValue}
  }
 }
 document.documentElement.lang=currentLanguage==='ms'?'ms':'en';
 if(translationObserver)translationObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
}
function initLanguageObserver(){
 if(translationObserver)return;
 translationObserver=new MutationObserver(()=>applyLanguage());
 translationObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
}

let pendingSaves=0;
function syncStatus(message){document.getElementById('workspace-sync-status')?.replaceChildren(document.createTextNode(message));}
function save(){
const organization=document.body.dataset.organizationId;if(!organization||document.body.dataset.canEdit!=='true')return;
const snapshot=JSON.stringify(state);pendingSaves++;syncStatus('Saving…');document.body.classList.add('is-saving');
saveQueue=saveQueue.then(async()=>{if(saveFailed)return false;const response=await fetch('/organizations/'+organization+'/workspace',{method:'PUT',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({data:JSON.parse(snapshot),version:workspaceVersion})});if(!response.ok)throw new Error('Not saved. Another member may have edited these records. Reload before continuing.');workspaceVersion=(await response.json()).version;syncStatus('Saved to organization');return true;}).catch(error=>{saveFailed=true;syncStatus(error.message);alert(error.message);return false;}).finally(()=>{pendingSaves--;if(!pendingSaves)document.body.classList.remove('is-saving');});return saveQueue;
}
window.addEventListener('beforeunload',event=>{if(pendingSaves||saveFailed){event.preventDefault();event.returnValue='';}});
async function refreshSharedWorkspace(){
if(!document.body.dataset.organizationId||pendingSaves||saveFailed||document.hidden||document.querySelector('dialog[open]')||document.activeElement?.matches('input,textarea,select'))return;
try{const response=await fetch('/organizations/'+document.body.dataset.organizationId+'/workspace',{headers:{Accept:'application/json'}});if(!response.ok){syncStatus('Unable to refresh organization data');return;}const latest=await response.json();if(latest.version>workspaceVersion){Object.assign(state,latest.data);workspaceVersion=latest.version;renderAll();syncStatus('Updated from organization');}}catch(error){syncStatus('Connection interrupted. Retrying…');}
}
setInterval(refreshSharedWorkspace,10000);
window.addEventListener('focus',refreshSharedWorkspace);

function go(id){ window.adaptNavigate?.(id === 'committee' ? 'organization' : id); }
document.querySelectorAll('.nav button[data-section]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.section)));
document.querySelectorAll('.nav-group-toggle').forEach(btn=>btn.addEventListener('click',()=>btn.parentElement.classList.toggle('open')));
document.querySelectorAll('.clickable-metric').forEach(card=>card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click()}}));
function openModal(id){ const modal=$(id); if(modal && !modal.open) modal.showModal(); } function closeModal(id){ $(id)?.close(); }

function toast(msg){let t=$('toast');t.textContent=translateText(msg);t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function statusBadge(s){let c=/not compliant|not complete|not ready/i.test(s)?'red':/compliant|complete|current|approved|closed|ready|yes/i.test(s)?'green':/overdue|not assessed|gap|no/i.test(s)?'red':/partial|due|assigned|review|open|pending|planned|scheduled/i.test(s)?'amber':'blue';return `<span class="badge ${c}">${esc(s)}</span>`}
function riskScore(l,s){return Number(l)*Number(s)} function riskBand(n){return n<=4?['Low','green']:n<=9?['Medium','amber']:['High','red']}
