 chemical:[['USECHH Regulations 2000','https://dosh.gov.my/wp-content/uploads/2025/01/Peraturan-peraturan-Keselamatan-dan-Kesihatan-Pekerjaan-Penggunaan-dan-Standard-Pendedahan-Bahan-Kimia-Berbahaya-Kepada-Kesihatan-Peraturan-USECHH-2000.pdf','Regulation'],['CLASS Regulations 2013','https://dosh.gov.my/wp-content/uploads/2026/04/Occupational-Safety-and-Health-Classification-Labelling-and-Safety-Data-Sheet-of-Hazardous-Chemicals-Regulations-2013.pdf','Regulation · supplier duties']],
