 'HIRARC':'hirarc','HIRARC Review':'hirarc','JMS & HIRARC':'hirarc','Risk Assessment':'hirarc',
 'PTW':'ptw','PTW applicability':'ptw','Hot Work PTW':'ptw','Equipment Register':'equipment',
